const upsertModuleTechnician = `-- name: UpsertModuleTechnician :one
INSERT INTO module_technicians (
    company_id,
    module_id,
    technician_id,
    can_view
) VALUES (
    $1,
    $2,
    $3,
    $4
)
ON CONFLICT (module_id, technician_id)
DO UPDATE SET can_view = EXCLUDED.can_view
RETURNING company_id, module_id, technician_id, can_view, created_at, updated_at
`

type UpsertModuleTechnicianParams struct {
	CompanyID    pgtype.UUID
	ModuleID     pgtype.UUID
	TechnicianID pgtype.UUID
	CanView      bool
}

func (q *Queries) UpsertModuleTechnician(ctx context.Context, arg UpsertModuleTechnicianParams) (ModuleTechnician, error) {
	row := q.db.QueryRow(ctx, upsertModuleTechnician,
		arg.CompanyID,
		arg.ModuleID,
		arg.TechnicianID,
		arg.CanView,
	)
	var i ModuleTechnician
	err := row.Scan(
		&i.CompanyID,
		&i.ModuleID,
		&i.TechnicianID,
		&i.CanView,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
